import java.util.*;

class SnakeGame {
  private final int width;
  private final int height;
  private final int[][] food;
  private int foodIndex;
  private final Deque<Integer> body = new ArrayDeque<>();
  private final Set<Integer> occupied = new HashSet<>();
  private int row;
  private int column;

  public SnakeGame(int width, int height, int[][] food) {
    this.width = width;
    this.height = height;
    this.food = food;
    body.addLast(0);
    occupied.add(0);
  }

  public int move(String direction) {
    int nextRow = row;
    int nextColumn = column;
    if (direction.equals("U")) nextRow--;
    else if (direction.equals("D")) nextRow++;
    else if (direction.equals("L")) nextColumn--;
    else if (direction.equals("R")) nextColumn++;
    if (nextRow < 0 || nextRow >= height || nextColumn < 0 || nextColumn >= width) return -1;

    int next = nextRow * width + nextColumn;
    boolean grows =
        foodIndex < food.length
            && food[foodIndex][0] == nextRow
            && food[foodIndex][1] == nextColumn;
    if (!grows) occupied.remove(body.removeFirst());
    if (occupied.contains(next)) return -1;

    body.addLast(next);
    occupied.add(next);
    row = nextRow;
    column = nextColumn;
    if (grows) foodIndex++;
    return foodIndex;
  }
}
